import re, glob, datetime, collections

sev_re = re.compile(r'\[(ERROR|WARNING|INFO|DEBUG)\]')
entries = []  # (date, sev)
for f in sorted(glob.glob('/app/logs/*.log')):
    fname = f.split('/')[-1]
    date_str = fname.split('_')[0]
    d = datetime.date.fromisoformat(date_str)
    for line in open(f, errors='replace'):
        m = sev_re.search(line)
        if not m: 
            print("NO SEV:", repr(line)); continue
        entries.append((d, m.group(1)))

def sum_sevs(ds):
    c = {'ERROR':0,'WARNING':0,'INFO':0}
    for d,s in entries:
        if d in ds:
            if s in c: c[s]+=1
    return c

today = datetime.date(2025,8,12)
last7 = {today - datetime.timedelta(days=k) for k in range(0,7)}
last30 = {today - datetime.timedelta(days=k) for k in range(0,30)}
mtd = {datetime.date(2025,8,1) + datetime.timedelta(days=k) for k in range(0,12)}
all_d = {e[0] for e in entries}

for name, ds in [('today',{today}),('last_7_days',last7),('last_30_days',last30),('month_to_date',mtd)]:
    c = sum_sevs(ds)
    print(name, dict(c))

c = sum_sevs(all_d)
print('total', dict(c))
